#include "profiles/whj2.hpp"
#include "scene_images.hpp"
#include "animation.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)return 2;whj2::AnimationLayer segment{"video",18,1,0,{qlie::Bytes(162),qlie::Bytes(162),qlie::Bytes(162),qlie::Bytes(162)}};for(unsigned i=0;i<4;i++){auto&k=segment.keys[i];unsigned t=i*1000;for(unsigned b=0;b<4;b++)k[b]=(t>>(8*b))&255;k[4]=i==3?0:4;k[6]=i==2?1:0;}segment.keys[3][0x34]=1;segment.keys[3][0x89]=1;
 if(whj2::sampleAnimation(segment,1500).mediaTime!=1500||whj2::sampleAnimation(segment,2500).mediaTime!=500||whj2::sampleAnimation(segment,3500).mediaTime!=1500)throw std::runtime_error("Contiguous video keys or loop offset restarted incorrectly");qlie::Assets assets(argv[1],whj2::profile::archives);whj2::SceneImages scene(assets);scene.command("^bg1,file:ev/04_02_1_90.b");qlie::Bytes first(1280*720*4),middle(first.size()),loop(first.size());scene.update(100);scene.draw(first);scene.update(900);scene.draw(middle);if(first==middle)throw std::runtime_error("Original CG frames did not animate");scene.update(1766);scene.draw(loop);if(loop!=first)throw std::runtime_error("CG keyframe loop did not return to same media time");auto saved=scene.save();whj2::SceneImages restored(assets);restored.restore(saved);restored.draw(loop);if(loop!=first)throw std::runtime_error("CG loop phase lost on restore");scene.update(2666);scene.draw(loop);if(loop!=first)throw std::runtime_error("Repeated CG loop stopped");std::cout<<"PASS original CG media time100/1000/2766/5432, repeated loop and restore\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
